<!DOCTYPE html>
<html lang="ru">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">

    <link href="https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css" rel="stylesheet">
    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@6.4.0/css/all.min.css">
    <!-- Добавляем шрифт Mulish -->
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Mulish:ital,wght@0,200..1000;1,200..1000&display=swap" rel="stylesheet">
    <style>

         :root {
    --primary-text: #000000;
    --secondary-text: rgba(0,0,0,0.6);
    --nav-text: rgba(0,0,0,0.302);
    --block-bg: #F0F4F7;
    --main-bg: #FFFFFF;
    --accent-active: #E30613;
    --accent-inactive: rgba(227,6,19,0.2);
    --mobile-breakpoint: 768px;
    --tablet-breakpoint: 1024px;
    --mobile-padding: 0.1rem;
    --tablet-padding: 1.5rem;
}






.module-number-text {
    color: var(--accent-active);
    font-weight: bold;
}

.module-title-text {
    color: var(--primary-text);
}












 /*свойство для подсветки "База ИИ" в хлебных крошках при наведении */
.breadcrumb-item {
    cursor: pointer;
    transition: color 0.3s ease;
    text-decoration: none;
}

.breadcrumb-item:hover { 
    color: var(--accent-active) !important; 
}
.fa-home {
    transition: color 0.3s ease;
}

.fa-home:hover {
    color: var(--accent-active) !important;
}














/* ===== MOBILE FIRST ТИПОГРАФИЯ ===== */
h1 { font-size: 1.75rem; line-height: 1.2; }
h2 { font-size: 1.5rem; }
h3 { font-size: 1.25rem; }
.text-block { line-height: 1.6; max-width: 100%; }

        body {
            font-family: "Mulish", -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background-color: var(--main-bg);
            color: var(--primary-text);
            line-height: 1.6;
        }



/* ===== АДАПТИВНЫЕ ТАБЫ ===== */
.tab-navigation {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.5rem;
    width: 100%;
}
.tab-button i {
        font-size: 0.7rem !important;
        margin-right: 0 !important;
        margin-bottom: 0.1rem;
    }

.tab-button {
    transition: all 0.3s ease;
    border-bottom: 2px solid transparent;
    padding: 0.25rem 0.5rem;
    min-height: 44px;
    justify-content: center;
    border-radius: 8px;
    margin-bottom: 0.25rem;
    width: 100%;
    display: flex;
    align-items: center;
    text-align: center;
    cursor: pointer;
    font-size: 0.9rem;


     flex-direction: row; /* По умолчанию - иконка слева */
    gap: 0.3rem;
    transition: all 0.3s ease;
}  

.tab-button.active {
    color: var(--accent-active);
    border-bottom-color: var(--accent-active);
}

.tab-button:hover {
    color: var(--accent-active);
    background-color: var(--block-bg);
}




/* ===== АДАПТИВНЫЕ КРАСНЫЕ КНОПКИ CTA ===== */
.ai-module-content .cta-button,
.ai-module-content .cta-button * {
    background: var(--accent-active) !important;
    color: white !important;
    border-radius: 8px !important;
    text-decoration: none !important;
    font-weight: 600 !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    transition: all 0.3s ease !important;
    border: none !important;
    cursor: pointer !important;
    text-align: center !important;
    padding: 0.75rem 1.5rem !important;
    margin: 0.5rem !important;
    font-size: 0.9rem !important;
    min-height: 44px !important;
    white-space: nowrap !important; /* ВАЖНО: запрет переноса */
}



.ai-module-content .cta-button:hover,
.ai-module-content .cta-button:hover * {
    background: #c4050f !important;
    transform: translateY(-2px) !important;
    box-shadow: 0 8px 25px rgba(227, 6, 19, 0.3) !important;
}

/* Специфичные стили для кнопок в подвале */
.footer-navigation .cta-button {
    width: 100% !important;
    max-width: 500px !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
}





        .hero-section {
            background: linear-gradient(135deg, var(--block-bg) 0%, #ffffff 100%);
            border-radius: 16px;
            margin: 2rem 0;
            padding: 3rem;
            text-align: center;
            position: relative;
            overflow: hidden;
        }

        .hero-section::before {
            content: '';
            position: absolute;
            top: -50%;
            left: -50%;
            width: 200%;
            height: 200%;
            background: radial-gradient(circle, var(--accent-inactive) 0%, transparent 70%);
            opacity: 0.1;
            animation: float 6s ease-in-out infinite;
        }

        @keyframes float {
            0%, 100% { transform: translateY(-10px) rotate(0deg); }
            50% { transform: translateY(10px) rotate(180deg); }
        }

        .hero-content {
            position: relative;
            z-index: 2;
        }

        .cta-button {
            background: var(--accent-active);
            color: white;
            padding: 1rem 2rem;
            border-radius: 8px;
            text-decoration: none;
            font-weight: 600;
            display: inline-block;
            margin: 1rem;
            transition: all 0.3s ease;
            border: none;
            cursor: pointer;
        }

        .cta-button:hover {
            background: #c4050f;
            transform: translateY(-2px);
            box-shadow: 0 8px 25px rgba(227, 6, 19, 0.3);
            color: white;
            text-decoration: none;
        }

        .module-card {
            background: var(--block-bg);
            border-radius: 12px;
            padding: 2rem;
            margin: 1.5rem 0;
            transition: all 0.3s ease;
            cursor: pointer;
            border: 2px solid transparent;
            position: relative;
            overflow: hidden;
        }

        .module-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: -100%;
            width: 100%;
            height: 100%;
            background: linear-gradient(90deg, transparent, rgba(227, 6, 19, 0.1), transparent);
            transition: left 0.5s ease;
        }

        .module-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 12px 30px rgba(0,0,0,0.1);
            border-color: var(--accent-active);
            background: white;
        }

        .module-card:hover::before {
            left: 100%;
        }

        .module-number {
            background: var(--accent-active);
            color: white;
            width: 50px;
            height: 50px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            font-size: 1.2rem;
            margin-bottom: 1rem;
        }

        .module-title {
            font-size: 1.5rem;
            font-weight: bold;
            margin: 1rem 0 0.5rem 0;
            color: var(--primary-text);
        }

        .module-description {
            color: var(--secondary-text);
            font-size: 1rem;
            line-height: 1.6;
        }

        .module-stats {
            display: flex;
            align-items: center;
            gap: 1rem;
            margin-top: 1rem;
            font-size: 0.9rem;
            color: var(--nav-text);
        }

        .difficulty-badge {
            padding: 0.25rem 0.75rem;
            border-radius: 20px;
            font-size: 0.8rem;
            font-weight: 500;
        }

        .difficulty-beginner {
            background: #e8f5e8;
            color: #2d5a2d;
        }

        .difficulty-intermediate {
            background: #fff3cd;
            color: #856404;
        }

        .difficulty-advanced {
            background: #f8d7da;
            color: #721c24;
        }

        .feature-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 1.5rem;
            margin: 3rem 0;
        }

        .feature-item {
            text-align: center;
            padding: 1.5rem;
            background: white;
            border-radius: 8px;
            border: 1px solid #e5e5e5;
        }

        .feature-icon {
            font-size: 2.5rem;
            color: var(--accent-active);
            margin-bottom: 1rem;
        }

        .stats-section {
            background: var(--block-bg);
            border-radius: 12px;
            padding: 2rem;
            margin: 3rem 0;
            text-align: center;
        }

        .stats-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
            gap: 2rem;
            margin-top: 2rem;
        }

        .stat-item {
            text-align: center;
        }

        .stat-number {
            font-size: 2.5rem;
            font-weight: bold;
            color: var(--accent-active);
            margin-bottom: 0.5rem;
        }

        .stat-label {
            color: var(--secondary-text);
            font-size: 0.9rem;
        }

        @media (max-width: 768px) {
            .hero-section {
                padding: 2rem 1rem;
            }

            .module-card {
                padding: 1.5rem;
            }

            .module-number {
                width: 40px;
                height: 40px;
                font-size: 1rem;
            }

            .module-title {
                font-size: 1.3rem;
            }
        }







