            <div class="hero-content">
                <h1 class="text-5xl font-bold mb-6">
                    Освойте ИИ <span style="color: var(--accent-active);">в несколько шагов</span>
                </h1>
                <p class="text-xl mb-8 max-w-3xl mx-auto" style="color: var(--secondary-text);">
                    Искусственный интеллект больше не магия - это инструмент, которым может овладеть каждый. Пройдите путь от полного новичка до уверенного пользователя ИИ и откройте для себя технологии, которые уже меняют мир.</p>
                <div class="flex flex-wrap justify-center gap-4">
                    <a href="#modules" class="cta-button">
                        <i class="fas fa-rocket mr-2"></i>
                        Программа обучения
                    </a>
                    <a href="#about" class="cta-button" style="background: white; color: var(--accent-active); border: 2px solid var(--accent-active);">
                        <i class="fas fa-info-circle mr-2"></i>
                        Почему эта база знаний
                    </a>
                </div>
            </div>
        </div>

        <!-- Статистика -->
        <div class="stats-section">
            <h2 class="text-2xl font-bold mb-4">Что вас ждет</h2>
            <div class="stats-grid">
                <div class="stat-item">
                    <div class="stat-number">7</div>
                    <div class="stat-label">Модулей обучения</div>
                </div>
                <div class="stat-item">
                    <div class="stat-number">50+</div>
                    <div class="stat-label">Практических инструментов</div>
                </div>
                <div class="stat-item">
                    <div class="stat-number">100%</div>
                    <div class="stat-label">Актуальной информации</div>
                </div>
                <div class="stat-item">
                    <div class="stat-number">2025</div>
                    <div class="stat-label">Год релиза</div>
                </div>
            </div>
        </div>

        <!-- Особенности -->
        <div class="feature-grid">
            <div class="feature-item">
                <div class="feature-icon">
                    <i class="fas fa-graduation-cap"></i>
                </div>
                <h3 class="text-lg font-semibold mb-2">От новичка до эксперта</h3>
                <p class="text-sm" style="color: var(--secondary-text);">
                    Структурированное обучение с постепенным усложнением материала
                </p>
            </div>

            <div class="feature-item">
                <div class="feature-icon">
                    <i class="fas fa-tools"></i>
                </div>
                <h3 class="text-lg font-semibold mb-2">Практические инструменты</h3>
                <p class="text-sm" style="color: var(--secondary-text);">
                    Реальные решения и сервисы, которые можно применить сразу
                </p>
            </div>

            <div class="feature-item">
                <div class="feature-icon">
                    <i class="fas fa-sync-alt"></i>
                </div>
                <h3 class="text-lg font-semibold mb-2">Актуальные данные</h3>
                <p class="text-sm" style="color: var(--secondary-text);">
                    Последние модели, тренды и технологии 2025 года
                </p>
            </div>
        </div>

        <!-- Модули обучения -->
        <div id="modules" class="mt-16">
            <h2 class="text-4xl font-bold text-center mb-4">Программа обучения</h2>
            <p class="text-xl text-center mb-12" style="color: var(--secondary-text);">
                7 комплексных модулей для полного понимания ИИ
            </p>

            <!-- Модуль 1 -->
            <div class="module-card">
    <a href="https://tu.by/ai-module-1/" target="_blank" 
       style="text-decoration: none; color: inherit; display: block; cursor: pointer;">
                <div class="flex items-start gap-4">

                    <div class="flex-1">
                        <h3 class="module-title">
                            <span class="module-number-text">Модуль 1</span></br></br>
                            <span class="module-title-text"> ИИ сегодня - Простая картина мира </span>
                        <p class="module-description">
                            Введение в мир искусственного интеллекта. Изучите иерархию ИИ → ML → Deep Learning → Generative AI → LLM. 
                            Узнайте об истории развития, текущих трендах и ключевых терминах. Идеальная отправная точка для понимания современного ИИ.
                        </p>
                        <div class="module-stats">
                            <span class="difficulty-badge difficulty-beginner">Новичок</span>
                            <span><i class="fas fa-brain mr-1"></i>Основы ИИ</span>
                            <span><i class="fas fa-history mr-1"></i>История развития</span>
                            <span><i class="fas fa-chart-line mr-1"></i>Тренды 2025</span>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Модуль 2 -->
            <div class="module-card">
    <a href="https://tu.by/ai-module-2/" target="_blank" 
       style="text-decoration: none; color: inherit; display: block; cursor: pointer;">
                <div class="flex items-start gap-4">
                    <div class="flex-1">
                        <h3 class="module-title">
                            <span class="module-number-text">Модуль 2</span></br></br>

                            <span class="module-title-text">Большие языковые модели - Как это работает</h3>
                        <p class="module-description">
                            Разберитесь в принципах работы LLM доступным языком. Узнайте про токены, контекстные окна, температуру генерации. 
                            Поймите, почему ChatGPT "понимает" вас и как модели обучаются на текстах всего интернета.
                        </p>
                        <div class="module-stats">
                            <span class="difficulty-badge difficulty-beginner">Новичок</span>
                            <span><i class="fas fa-cogs mr-1"></i>Принципы работы</span>
                            <span><i class="fas fa-language mr-1"></i>Обработка языка</span>
                            <span><i class="fas fa-graduation-cap mr-1"></i>Обучение моделей</span>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Модуль 3 -->
            <div class="module-card">
    <a href="https://tu.by/ai-module-3/" target="_blank" 
       style="text-decoration: none; color: inherit; display: block; cursor: pointer;">
                <div class="flex items-start gap-4">

                    <div class="flex-1">
                        <h3 class="module-title">
                            <span class="module-number-text">Модуль 3</span></br></br>
                            <span class="module-title-text"> Топовые модели 2025: Сравнение лидеров</h3>
                        <p class="module-description">
                            Подробный обзор лучших LLM 2025 года: GPT-5, Claude 4, Gemini 2.5 Pro, DeepSeek V3.2 
                            Включая китайские модели, российские и европейские разработки. 
                            Сравнительные характеристики и рекомендации по выбору.
                        </p>
                        <div class="module-stats">
                            <span class="difficulty-badge difficulty-intermediate">Средний</span>
                            <span><i class="fas fa-trophy mr-1"></i>Топ модели</span>
                            <span><i class="fas fa-globe mr-1"></i>Международный обзор</span>
                            <span><i class="fas fa-balance-scale mr-1"></i>Сравнение</span>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Модуль 4 -->
            <div class="module-card">
    <a href="https://tu.by/ai-module-4/" target="_blank" 
       style="text-decoration: none; color: inherit; display: block; cursor: pointer;">
                <div class="flex items-start gap-4">

                    <div class="flex-1">
                        <h3 class="module-title">
                            <span class="module-number-text">Модуль 4</span></br></br>
                            <span class="module-title-text"> Prompt Engineering: Искусство общения с ИИ</h3>
                        <p class="module-description">
                            Научитесь создавать эффективные промпты. Изучите анатомию промпта, техники Zero-shot, Few-shot, Chain-of-Thought. 
                            Получите практические навыки создания промптов с помощью интерактивного конструктора.
                        </p>
                        <div class="module-stats">
                            <span class="difficulty-badge difficulty-intermediate">Средний</span>
                            <span><i class="fas fa-edit mr-1"></i>Техники промптов</span>
                            <span><i class="fas fa-language mr-1"></i>Готовые шаблоны</span>
                            <span><i class="fas fa-tools mr-1"></i>Конструктор</span>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Модуль 5 -->
            <div class="module-card">
    <a href="https://tu.by/ai-module-5/" target="_blank" 
       style="text-decoration: none; color: inherit; display: block; cursor: pointer;">
                <div class="flex items-start gap-4">

                    <div class="flex-1">
                        <h3 class="module-title">
                            <span class="module-number-text">Модуль 5</span></br></br>
                            <span class="module-title-text"> Генеративные медиа: От текста к изображениям, видео, аудио</h3>
                        <p class="module-description">
                            Обзор инструментов для генерации изображений (Nano banana, DALL-E, Midjourney, Stable Diffusion), 
                            видео (Veo 3, Sora, Runway, Seedream) и аудио (Suno, ElevenLabs). 
                            Продвинутые техники промпта для генерации изображений.
                        </p>
                        <div class="module-stats">
                            <span class="difficulty-badge difficulty-intermediate">Средний</span>
                            <span><i class="fas fa-image mr-1"></i>Генерация изображений</span>
                            <span><i class="fas fa-video mr-1"></i>Создание видео</span>
                            <span><i class="fas fa-music mr-1"></i>Аудио контент</span>
                        </div>
                    </div>
                </div>
            </div>

            <!-- Модуль 6 -->
            <div class="module-card">
    <a href="https://tu.by/ai-module-6/" target="_blank" 
       style="text-decoration: none; color: inherit; display: block; cursor: pointer;">
                <div class="flex items-start gap-4">

                    <div class="flex-1">
                        <h3 class="module-title">
                            <span class="module-number-text">Модуль 6</span></br></br>
                            <span class="module-title-text"> ИИ-агенты: Автономные помощники</h3>
                        <p class="module-description">
                            Разберитесь в разнице между обычными чат-ботами и умными ИИ-агентами. 
                            Узнайте, что такое системы из нескольких агентов и где их использовать в бизнесе. 
                            Поймите, как автономные системы на ИИ работают сами и сотрудничают между собой.
                        </p>
                        <div class="module-stats">
                            <span class="difficulty-badge difficulty-advanced">Продвинутый</span>
                            <span><i class="fas fa-robot mr-1"></i>ИИ-агенты</span>
                            <span><i class="fas fa-network-wired mr-1"></i>Мульти-агентность</span>
                            <span><i class="fas fa-code-branch mr-1"></i>Workflow</span>
                        </div>
                    </div>
                </div>
            </div>



            <!-- Модуль 7 -->
            <div class="module-card">
    <a href="https://tu.by/ai-module-7/" target="_blank" 
       style="text-decoration: none; color: inherit; display: block; cursor: pointer;">
                <div class="flex items-start gap-4">

                    <div class="flex-1">
                        <h3 class="module-title">
                            <span class="module-number-text">Модуль 7</span></br></br>
                            <span class="module-title-text"> Этика, ограничения и будущее ИИ</h3>
                        <p class="module-description">
                            Ответственное использование ИИ: этические дилеммы, bias, privacy, влияние на рынок труда. 
                            Текущие ограничения (галлюцинации, reasoning), вопросы безопасности (jailbreaking, prompt injection). 
                            Прогнозы развития AGI и практический чек-лист ответственного применения.
                        </p>
                        <div class="module-stats">
                            <span class="difficulty-badge difficulty-advanced">Продвинутый</span>
                            <span><i class="fas fa-shield-alt mr-1"></i>Этика и безопасность</span>
                            <span><i class="fas fa-exclamation-triangle mr-1"></i>Ограничения</span>
                            <span><i class="fas fa-language mr-1"></i>Будущее AGI</span>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <!-- О курсе -->
        <div id="about" class="mt-16">
            <div class="stats-section">
                <h2 class="text-3xl font-bold mb-6">Почему эта база знаний</h2>
                <div class="grid md:grid-cols-2 gap-8 text-left">
                    <div>
                        <h3 class="text-xl font-semibold mb-4">
                            <i class="fas fa-pencil-alt mr-2" style="color: var(--accent-active);"></i>
                           Доступность для новичков

                        </h3>
                        <p style="color: var(--secondary-text);">
                           Сложные концепции изложены доступно и понятно. Материал адаптирован специально для тех, кто только начинает знакомство с ИИ. Подходит для людей без опыта в программировании или технических областях.
 </div>

                    <div>
                        <h3 class="text-xl font-semibold mb-4">
                            <i class="fas fa-clock mr-2" style="color: var(--accent-active);"></i>
                            Актуальность 2025
                        </h3>
                        <p style="color: var(--secondary-text);">
                             Все данные обновлены за октябрь 2025 года. Включены последние модели, международные разработки и свежие тренды индустрии.
 </p>
                    </div>

                    <div>
                        <h3 class="text-xl font-semibold mb-4">
                            <i class="fas fa-book-open mr-2" style="color: var(--accent-active);"></i>
                            Практическая направленность
                        </h3>
                        <p style="color: var(--secondary-text);">
                            Каждый модуль содержит интерактивные элементы, конкретные инструменты 
                            и пошаговые инструкции. Теория подкреплена практикой.
                        </p>
                    </div>

                    <div>
                        <h3 class="text-xl font-semibold mb-4">
                            <i class="fas fa-graduation-cap mr-2" style="color: var(--accent-active);"></i>
                            Структурированное обучение
                        </h3>
                        <p style="color: var(--secondary-text);">
                            Логичная последовательность от основ к продвинутым темам. Можете изучать модули в любом порядке или следовать рекомендуемому пути.

                        </p>
                    </div>
                </div>
            </div>
        </div>

        <!-- Призыв к действию -->
        <div class="hero-section mt-16">
            <div class="hero-content">
                <h2 class="text-3xl font-bold mb-4">Готовы освоить ИИ?
</h2>
                <p class="text-lg mb-8" style="color: var(--secondary-text);">
                    Присоединяйтесь к тысячам людей, которые уже изучают искусственный интеллект и открывают для себя новые возможности в работе и жизни

                </p>
                <a href="https://tu.by/ai-module-1/" class="cta-button">
                    <i class="fas fa-play mr-2"></i>
                    Начать с Модуля 1
                </a>
            </div>
        </div>
    </div>



    <script>
        // Плавная прокрутка к якорям
        document.addEventListener('DOMContentLoaded', function() {
            const links = document.querySelectorAll('a[href^="#"]');

            links.forEach(link => {
                link.addEventListener('click', function(e) {
                    e.preventDefault();
                    const targetId = this.getAttribute('href');
                    const targetElement = document.querySelector(targetId);

                    if (targetElement) {
                        targetElement.scrollIntoView({
                            behavior: 'smooth',
                            block: 'start'
                        });
                    }
                });
            });
        });

        // Анимация появления элементов при прокрутке
        const observerOptions = {
            threshold: 0.1,
            rootMargin: '0px 0px -50px 0px'
        };

        const observer = new IntersectionObserver(function(entries) {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.style.opacity = '1';
                    entry.target.style.transform = 'translateY(0)';
                }
            });
        }, observerOptions);

        // Применяем анимацию к карточкам модулей
        document.addEventListener('DOMContentLoaded', function() {
            const moduleCards = document.querySelectorAll('.module-card');

            moduleCards.forEach((card, index) => {
                card.style.opacity = '0';
                card.style.transform = 'translateY(30px)';
                card.style.transition = `opacity 0.6s ease ${index * 0.1}s, transform 0.6s ease ${index * 0.1}s`;
                observer.observe(card);
            });
        });
    </script>
</body>
</html>
<!-- /wp:html -->[/et_pb_text][/et_pb_column]
			[/et_pb_row]
		[/et_pb_section]

