/* ===== МЕДИА-ЗАПРОСЫ ДЛЯ МАЛЕНЬКИХ ЭКРАНОВ ===== */

/* Мобильная версия - ТАБЫ ПО ДВЕ В РЯД */
@media (max-width: 768px) {
    .tab-navigation {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 0.5rem;
        width: 100%;
    }

    .tab-button {
        margin-bottom: 0 !important;
        min-height: 44px;
        font-size: 0.8rem;
        padding: 0.75rem 0.5rem;
        border-radius: 8px;
        border-bottom: 2px solid transparent;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        text-align: center;
        justify-content: center;
    }


    .tab-button.active {
        border-bottom-color: var(--accent-active);
    }

    .ai-module-content .cta-button,
    .ai-module-content .cta-button * {
        padding: 0.6rem 1.2rem !important;
        margin: 0.4rem !important;
        font-size: 0.85rem !important;
        min-height: 40px !important;
    }

    .footer-navigation .nav-button:last-child {
        max-width: 180px !important;
        min-width: 150px !important;
    }

    .footer-navigation {
        gap: 0.75rem !important;
        flex-wrap: wrap !important;
        justify-content: center !important;
    }

    .footer-navigation .cta-button { max-width: 220px !important; }

    /* Упрощаем hover-эффекты на мобильных */
    .hierarchy-level:hover { transform: none; }
    .example-card:hover { transform: none; }

    /* Улучшаем отображение конструктора промптов */
    .grid.grid-cols-1.lg\:grid-cols-2.gap-8 {
        grid-template-columns: 1fr;
        gap: 1rem;
    }

    /* Улучшаем читаемость длинного контента */
    .result-content {
        font-size: 0.75rem;
        min-height: 150px;
        max-height: 300px;
    }
}









/* Для очень маленьких экранов */
@media (max-width: 480px) {
    .tab-navigation {
        grid-template-columns: 1fr 1fr;
        gap: 0.4rem;
    }

    .tab-button {
        padding: 0.6rem 0.3rem !important;
        font-size: 0.75rem !important;
        min-height: 40px !important;
    }


    /* Уменьшаем иконки */
    .tab-button i {
        font-size: 0.7rem !important;
        margin-right: 0.3rem !important;
    }

    /* Уменьшаем отступы контента */
    .max-w-6xl.mx-auto.px-4 {
        padding-left: 0.5rem !important;
        padding-right: 0.5rem !important;
    }

    /* Уменьшаем заголовки */
    h1 { font-size: 1.5rem; }
    h2 { font-size: 1.25rem; }
    h3 { font-size: 1.1rem; }

    /* Уменьшаем карточки */
    .anatomy-card, .template-card, .builder-section {
        padding: 0.75rem;
    }

    /* Улучшаем читаемость текста */
    .text-block, .section-description, .example-text {
        font-size: 0.85rem;
        line-height: 1.5;
    }
}











/* Для экстремально маленьких экранов (менее 360px) */
@media (max-width: 360px) {
    .tab-navigation {
        grid-template-columns: 1fr 1fr;
        gap: 0.3rem;
    }

.tab-button span:not(.fa) {
        display: inline !important; /* ✅ ВОССТАНАВЛИВАЕМ ТЕКСТ *//* Убираем скрытие текста на маленьких экранах */
    }

   .tab-button {
        padding: 0.5rem 0.25rem !important;
        font-size: 0.7rem !important;
        min-height: 36px !important;
    }

    .tab-button i {
        font-size: 0.6rem !important; /* ✅ Уменьшаем иконки вместо скрытия текста */
        margin-right: 0.2rem !important;
    }

    .flip-card {
        height: 100px;
    }

    .btn-primary, .btn-secondary {
        padding: 0.6rem 0.8rem;
        font-size: 0.8rem;
    }

    /* Уменьшаем все шрифты */
    body {
        font-size: 0.9rem;
    }









    /* Можно скрыть текст и оставить только иконки на самых маленьких экранах */
    .tab-button span:not(.fa) {
        display: none;
    }

    .tab-button i {
        margin-right: 0 !important;
        font-size: 0.8rem !important;
    }

    /* Еще больше уменьшаем отступы */
    .max-w-6xl.mx-auto.px-4 {
        padding-left: 0.25rem !important;
        padding-right: 0.25rem !important;
    }

    /* Уменьшаем кнопки */
    .ai-module-content .cta-button,
    .ai-module-content .cta-button * {
        padding: 0.5rem 1rem !important;
        font-size: 0.8rem !important;
        min-height: 36px !important;
    }

    /* Уменьшаем flip-карточки */
    .flip-card {
        height: 120px;
        margin: 0.5rem 0;
    }

    .flip-card-front, .flip-card-back {
        padding: 0.5rem;
        font-size: 0.75rem;
    }
}

@media (max-width: 768px) {
    .flip-card-front, .flip-card-back {
        padding: 0.5rem;
        font-size: 0.8em;
        line-height: 1.3;
    }
}

@media (max-width: 480px) {
    .flip-card-front, .flip-card-back {
        padding: 0.25rem;
        font-size: 0.75em;
        line-height: 1.2;
    }
}








/* Планшетная версия */
@media (min-width: 769px) and (max-width: 1024px) {
    .tab-navigation {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 0.5rem;
        width: 100%;
    }

    .tab-button {
        margin-bottom: 0 !important;
        min-height: 44px;
        font-size: 0.85rem;
        padding: 0.8rem 0.5rem;
    }

    h1 { font-size: 2rem; }
    h2 { font-size: 1.75rem; }

    .ai-module-content .cta-button,
    .ai-module-content .cta-button * {
        padding: 0.85rem 1.75rem !important;
        margin: 0.75rem !important;
        font-size: 0.95rem !important;
        min-height: 46px !important;
    }

    .example-grid { grid-template-columns: repeat(2, 1fr); }
    .chart-container { height: 250px; }

    .footer-navigation {
        flex-direction: row;
        justify-content: space-between;
        gap: 1.5rem;
    }

    .nav-button {
        width: auto !important;
        max-width: 200px !important;
        flex: 1;
    }

    .hierarchy-level:hover { transform: translateX(8px); }
    .example-card:hover { transform: translateY(-2px); }

    /* Улучшаем конструктор для планшетов */
    .anatomy-section {
        grid-template-columns: repeat(2, 1fr);
    }

    .format-grid {
        grid-template-columns: repeat(3, 1fr);
    }
}












/* Десктопная версия */
@media (min-width: 1025px) {
    .tab-navigation {
        display: flex;
        flex-direction: row;
        gap: 0.25rem;
        width: 100%;
    }

    .tab-button {
        width: 100%;
        flex: 1;
        margin-bottom: 0.25rem;
    }

    h1 { font-size: 2.5rem; }
    h2 { font-size: 2rem; }

    .breadcrumb { flex-wrap: nowrap; font-size: 1rem; }
    .module-counter { text-align: right; margin-top: 0; width: auto; }

    .ai-module-content .cta-button,
    .ai-module-content .cta-button * {
        padding: 1rem 2rem !important;
        margin: 1rem !important;
        font-size: 1rem !important;
        min-height: 48px !important;
    }

    .ai-hierarchy { padding: 2rem; }
    .hierarchy-level:hover { transform: translateX(8px); }
    .example-grid { grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); }
    .company-grid { grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); }
    .flip-card { height: 200px; }
    .chart-container { height: 400px; }
    .text-block { max-width: 100%; }
    .content-section { margin-bottom: 3rem; }

    .footer-navigation {
        flex-direction: row;
        justify-content: space-between;
        gap: 1.5rem;
    }

    .nav-button {
        width: auto !important;
        max-width: 200px !important;
        flex: 1;
    }

    .example-card:hover { transform: translateY(-2px); }

    /* Полная версия конструктора для десктопа */
    .anatomy-section {
        grid-template-columns: repeat(3, 1fr);
    }

    .format-grid {
        grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
    }

    .prompt-result-section {
        position: sticky;
        top: 100px;
    }
}












