        hint: "Опытный разработчик с знанием различных языков программирования и архитектуры",
        taskExample: "Создай REST API для системы управления задачами",
        contextExample: "Python Flask, PostgreSQL, аутентификация JWT, документация Swagger",
        inputExample: "создание задач, обновление статуса, назначение пользователей, фильтрация",
        exampleTemplate: `Входные данные: сортировка массива, Python
Ответ: **Quick Sort**
\`\`\`python
def quicksort(arr):
    if len(arr) <= 1: return arr
    pivot = arr[len(arr) // 2]
    return quicksort([x for x in arr if x < pivot]) + [pivot] + quicksort([x for x in arr if x > pivot])
\`\`\``
    },
    historian: {
        hint: "Историк с глубоким пониманием исторических процессов и культурных контекстов",
        taskExample: "Проанализируй причины и последствия Октябрьской революции 1917 года",
        contextExample: "Научный подход, использование первоисточников, объективная оценка фактов",
        inputExample: "экономический кризис, Первая мировая война, социальные противоречия, политика царизма",
        exampleTemplate: `Входные данные: Древний Рим, падение, причины
Ответ: **Падение Западной Римской империи**
Внутренние: кризис власти, экономический упадок
Внешние: нашествие варваров, давление готов
Дата: 476 г. н.э.`
    },
    finance: {
        hint: "Финансовый эксперт с пониманием инвестиций, планирования и рынков",
        taskExample: "Составь личный финансовый план для семьи с доходом 100,000 руб/мес",
        contextExample: "Цель: покупка квартиры через 5 лет, есть ребенок, стабильная работа",
        inputExample: "накопления, инвестиции, страхование, ипотека, резервный фонд",
        exampleTemplate: `Входные данные: акции, облигации, 500,000 руб, 3 года
Ответ: **Портфель "Сбалансированный"**
60% облигации (стабильный доход)
30% акции голубых фишек (рост)
10% резерв (ликвидность)`
    },
    teacher: {
        hint: "Педагог с пониманием методик обучения и возрастной психологии",
        taskExample: "Разработай план урока по математике для 7 класса на тему 'Линейные уравнения'",
        contextExample: "45 минут, 25 учеников, разный уровень подготовки, интерактивные методы",
        inputExample: "объяснение теории, практические примеры, самостоятельная работа, домашнее задание",
        exampleTemplate: `Входные данные: английский язык, Present Simple, начинающие
Ответ: **Урок Present Simple**
Введение: что делаю каждый день (5 мин)
Правило: I/you/we/they + V1 (10 мин)
Практика: упражнения с картинками (20 мин)`
    },
    designer: {
        hint: "Дизайнер с пониманием композиции, цвета, типографики и пользовательского опыта",
        taskExample: "Создай концепцию дизайна мобильного приложения для доставки еды",
        contextExample: "Молодая аудитория, яркий стиль, удобная навигация, быстрое оформление заказов",
        inputExample: "главный экран, каталог, корзина, профиль, цветовая схема, типографика",
        exampleTemplate: `Входные данные: логотип, кофейня, уютная атмосфера
Ответ: **Концепция логотипа**
Стиль: минимализм с рукописными элементами
Цвета: теплый коричневый + кремовый
Символ: стилизованная кофейная чашка с паром`
    }
};

// Prompt templates for quick start
const promptTemplates = {
    recipe: {
        role: 'chef',
        task: 'Создай подробный рецепт блюда на основе указанных ингредиентов',
        context: 'Время приготовления до 45 минут, средний уровень сложности, пошаговые инструкции',
        format: 'Пошаговый план',
        examples: `Входные данные: курица, рис, овощи
Ответ: **Плов с курицей**
1. Обжарить курицу до золотистой корочки
2. Добавить морковь и лук
3. Засыпать промытый рис
4. Залить бульоном и тушить 20 минут`,
        inputData: 'говядина, картофель, морковь, лук, томатная паста'
    },
    travel: {
        role: 'traveler', 
        task: 'Составь детальный план путешествия с маршрутом и рекомендациями',
        context: 'Бюджет средний, первое посещение региона, интерес к культуре и достопримечательностям',
        format: 'Пошаговый план',
        examples: `Входные данные: Санкт-Петербург, 2 дня, музеи
Ответ: **День 1: Исторический центр**
09:00-Эрмитаж (3 часа)
13:00-Обед на Невском проспекте  
15:00-Прогулка по каналам
18:00-Исаакиевский собор`,
        inputData: 'Казань, 3 дня, семья с детьми, кремль, национальная кухня'
    },
    marketing: {
        role: 'marketer',
        task: 'Проанализируй ситуацию и предложи маркетинговую стратегию с конкретными шагами',
        context: 'Ограниченный бюджет, цифровые каналы продвижения, измеримые результаты',
        format: 'Пошаговый план',
        examples: `Входные данные: онлайн-школа, низкие продажи
Ответ: **Стратегия роста продаж**
1. Анализ конкурентов и ЦА
2. Бесплатные вебинары для привлечения
3. Email-воронка с полезным контентом
4. Партнерская программа`,
        inputData: 'интернет-магазин одежды, падение конверсии, высокая конкуренция'
    },
    code: {
        role: 'programmer',
        task: 'Проведи код-ревью и предложи улучшения с объяснением',
        context: 'Фокус на читаемость, производительность, следование best practices',
        format: 'Подробное объяснение',
        examples: `Входные данные: функция поиска в массиве
Ответ: **Анализ кода**
Проблемы: O(n²) сложность, нет обработки ошибок
Решение: использовать HashMap для O(1) поиска
Код: Map.get(key) вместо nested loops`,
        inputData: `function findUser(users, id) {
    for(let i = 0; i < users.length; i++) {
        if(users[i].id == id) return users[i];
    }
}`
    }
};

// DOM elements
let elements = {};

// Initialize when DOM is loaded
document.addEventListener('DOMContentLoaded', function() {
    // Get DOM elements
    elements = {
        roleSelect: document.getElementById('roleSelect'),
        taskInput: document.getElementById('taskInput'),
        contextInput: document.getElementById('contextInput'),
        formatInput: document.getElementById('formatInput'),
        examplesInput: document.getElementById('examplesInput'),
        inputDataField: document.getElementById('inputDataField'),
        generatedPrompt: document.getElementById('generatedPrompt'),
        copyBtn: document.getElementById('copyBtn'),
        clearBtn: document.getElementById('clearBtn'),
        generateBtn: document.getElementById('generateBtn'),
        roleHint: document.getElementById('roleHint'),
        taskExample: document.getElementById('taskExample'),
        contextExample: document.getElementById('contextExample'),
        exampleTemplate: document.getElementById('exampleTemplate'),
        inputExample: document.getElementById('inputExample')
    };

    // Event listeners
    if (elements.roleSelect) {
        elements.roleSelect.addEventListener('change', updateRoleInfo);
    }

    if (elements.generateBtn) {
        elements.generateBtn.addEventListener('click', generatePrompt);
    }

    if (elements.copyBtn) {
        elements.copyBtn.addEventListener('click', copyPrompt);
    }

    if (elements.clearBtn) {
        elements.clearBtn.addEventListener('click', clearForm);
    }

    // Format buttons
    document.querySelectorAll('.format-btn').forEach(btn => {
        btn.addEventListener('click', function() {
            // Remove active class from all buttons
            document.querySelectorAll('.format-btn').forEach(b => {
                b.classList.remove('bg-purple-200', 'border-purple-500');
            });

            // Add active class to clicked button
            this.classList.add('bg-purple-200', 'border-purple-500');

            // Set format input
            if (elements.formatInput) {
                elements.formatInput.value = this.dataset.format;
            }
        });
    });

    // Template buttons
    document.querySelectorAll('.template-btn').forEach(btn => {
        btn.addEventListener('click', function() {
            loadTemplate(this.dataset.template);
        });
    });

    // Example click handlers
    if (elements.taskExample) {
        elements.taskExample.addEventListener('click', function() {
            const roleValue = elements.roleSelect?.value;
            if (roleValue && roleData[roleValue]) {
                elements.taskInput.value = roleData[roleValue].taskExample;
            }
        });
    }

    if (elements.contextExample) {
        elements.contextExample.addEventListener('click', function() {
            const roleValue = elements.roleSelect?.value;
            if (roleValue && roleData[roleValue]) {
                elements.contextInput.value = roleData[roleValue].contextExample;
            }
        });
    }

    if (elements.exampleTemplate) {
        elements.exampleTemplate.addEventListener('click', function() {
            const roleValue = elements.roleSelect?.value;
            if (roleValue && roleData[roleValue]) {
                elements.examplesInput.value = roleData[roleValue].exampleTemplate;
            }
        });
    }

    if (elements.inputExample) {
        elements.inputExample.addEventListener('click', function() {
            const roleValue = elements.roleSelect?.value;
            if (roleValue && roleData[roleValue]) {
                elements.inputDataField.value = roleData[roleValue].inputExample;
            }
        });
    }

    // Auto-save functionality
    const inputElements = [elements.taskInput, elements.contextInput, elements.formatInput, elements.examplesInput, elements.inputDataField];
    inputElements.forEach(element => {
        if (element) {
            element.addEventListener('input', saveToLocalStorage);
        }
    });

    if (elements.roleSelect) {
        elements.roleSelect.addEventListener('change', saveToLocalStorage);
    }

    // Load from localStorage
    loadFromLocalStorage();
});

function updateRoleInfo() {
    const role = elements.roleSelect?.value;
    if (!role || !roleData[role]) {
        elements.roleHint && (elements.roleHint.textContent = '');
        elements.taskExample && (elements.taskExample.textContent = '');
        elements.contextExample && (elements.contextExample.textContent = '');
        elements.exampleTemplate && (elements.exampleTemplate.textContent = '');
        elements.inputExample && (elements.inputExample.textContent = '');
        return;
    }

    const data = roleData[role];

    if (elements.roleHint) {
        elements.roleHint.textContent = data.hint;
    }

    if (elements.taskExample) {
        elements.taskExample.textContent = `💡 Пример: ${data.taskExample}`;
    }

    if (elements.contextExample) {
        elements.contextExample.textContent = `💡 Пример: ${data.contextExample}`;
    }

    if (elements.exampleTemplate) {
        elements.exampleTemplate.textContent = `💡 Нажмите, чтобы вставить пример`;
    }

    if (elements.inputExample) {
        elements.inputExample.textContent = `💡 Пример: ${data.inputExample}`;
    }
}

function generatePrompt() {
    const role = elements.roleSelect?.value;
    const task = elements.taskInput?.value.trim();
    const context = elements.contextInput?.value.trim();
    const format = elements.formatInput?.value.trim();
    const examples = elements.examplesInput?.value.trim();
    const inputData = elements.inputDataField?.value.trim();

    if (!role) {
        alert('Пожалуйста, выберите роль');
        return;
    }

    if (!task) {
        alert('Пожалуйста, опишите задачу');
        return;
    }

    let prompt = '';

    // Role
    const roleInfo = roleData[role];
    if (roleInfo) {
        prompt += `Ты-${roleInfo.hint.toLowerCase()}.

`;
    }

    // Task
    prompt += `Задача: ${task}

`;

    // Context
    if (context) {
        prompt += `Контекст: ${context}

`;
    }

    // Format
    if (format) {
        prompt += `Формат ответа: ${format}

`;
    }

    // Examples
    if (examples) {
        prompt += `Пример:
${examples}

`;
    }

    // Input data
    if (inputData) {
        prompt += `Входные данные:
${inputData}`;
    }

    elements.generatedPrompt && (elements.generatedPrompt.textContent = prompt);
    elements.copyBtn && (elements.copyBtn.disabled = false);
}

function loadTemplate(templateName) {
    const template = promptTemplates[templateName];
    if (!template) return;

    // Set role
    if (elements.roleSelect) {
        elements.roleSelect.value = template.role;
        updateRoleInfo();
    }

    // Fill form fields
    if (elements.taskInput) elements.taskInput.value = template.task;
    if (elements.contextInput) elements.contextInput.value = template.context;
    if (elements.formatInput) elements.formatInput.value = template.format;
    if (elements.examplesInput) elements.examplesInput.value = template.examples;
    if (elements.inputDataField) elements.inputDataField.value = template.inputData;

    // Update format buttons
    document.querySelectorAll('.format-btn').forEach(btn => {
        btn.classList.remove('bg-purple-200', 'border-purple-500');
        if (btn.dataset.format === template.format) {
            btn.classList.add('bg-purple-200', 'border-purple-500');
        }
    });

    // Generate prompt
    generatePrompt();

    // Save to localStorage
    saveToLocalStorage();
}

function copyPrompt() {
    const promptText = elements.generatedPrompt?.textContent;
    if (!promptText) return;

    navigator.clipboard.writeText(promptText).then(() => {
        showNotification('Промпт скопирован в буфер обмена!');
    }).catch(() => {
        // Fallback for older browsers
        const textArea = document.createElement('textarea');
        textArea.value = promptText;
        document.body.appendChild(textArea);
        textArea.select();
        document.execCommand('copy');
        document.body.removeChild(textArea);
        showNotification('Промпт скопирован!');
    });
}

function clearForm() {
    const confirmClear = confirm('Очистить все поля? Это действие нельзя отменить.');
    if (!confirmClear) return;

    // Clear all form fields
    if (elements.roleSelect) elements.roleSelect.value = '';
    if (elements.taskInput) elements.taskInput.value = '';
    if (elements.contextInput) elements.contextInput.value = '';
    if (elements.formatInput) elements.formatInput.value = '';
    if (elements.examplesInput) elements.examplesInput.value = '';
    if (elements.inputDataField) elements.inputDataField.value = '';
    if (elements.generatedPrompt) elements.generatedPrompt.textContent = 'Заполните форму выше и нажмите "Создать промпт", чтобы увидеть результат...';

    // Clear format button selection
    document.querySelectorAll('.format-btn').forEach(btn => {
        btn.classList.remove('bg-purple-200', 'border-purple-500');
    });

    // Disable copy button
    if (elements.copyBtn) elements.copyBtn.disabled = true;

    // Update role info
    updateRoleInfo();

    // Clear localStorage
    localStorage.removeItem('promptConstructor');
}

function showNotification(message) {
    const notification = document.getElementById('notification');
    const notificationText = document.getElementById('notificationText');

    if (!notification || !notificationText) return;

    notificationText.textContent = message;
    notification.classList.remove('translate-x-full');

    setTimeout(() => {
        notification.classList.add('translate-x-full');
    }, 3000);
}

function saveToLocalStorage() {
    const data = {
        role: elements.roleSelect?.value || '',
        task: elements.taskInput?.value || '',
        context: elements.contextInput?.value || '',
        format: elements.formatInput?.value || '',
        examples: elements.examplesInput?.value || '',
        inputData: elements.inputDataField?.value || ''
    };

    localStorage.setItem('promptConstructor', JSON.stringify(data));
}

function loadFromLocalStorage() {
    try {
        const saved = localStorage.getItem('promptConstructor');
        if (!saved) return;

        const data = JSON.parse(saved);

        if (elements.roleSelect && data.role) {
            elements.roleSelect.value = data.role;
            updateRoleInfo();
        }
        if (elements.taskInput && data.task) elements.taskInput.value = data.task;
        if (elements.contextInput && data.context) elements.contextInput.value = data.context;
        if (elements.formatInput && data.format) {
            elements.formatInput.value = data.format;
            // Highlight corresponding format button
            document.querySelectorAll('.format-btn').forEach(btn => {
                if (btn.dataset.format === data.format) {
                    btn.classList.add('bg-purple-200', 'border-purple-500');
                }
            });
        }
        if (elements.examplesInput && data.examples) elements.examplesInput.value = data.examples;
        if (elements.inputDataField && data.inputData) elements.inputDataField.value = data.inputData;
    } catch (error) {
        console.error('Error loading from localStorage:', error);
    }
}



</script></body>
</html>
