                <!-- Структура JSON схемы -->
                <section class="content-section">
                    <h2 class="text-3xl font-bold mb-6">
                        <i class="fas fa-sitemap mr-3" style="color: var(--accent-active);"></i>
                        Анатомия JSON - схемы для изображений
                    </h2>

                    <p class="text-lg mb-6">
                        Эффективная JSON - схема разбивает визуальную задачу на логические блоки. Каждый блок отвечает 
                        за свой аспект изображения, что даёт полный контроль над результатом.
                    </p>

                    <div class="space-y-4">
                        <!-- Элемент 1: Цель и стиль -->
                        <div class="accordion">
                            <div class="accordion-header" onclick="toggleAccordion(this)">
                                <div class="flex justify-between items-center">
                                    <h3 class="font-semibold">
                                        <i class="fas fa-bullseye mr-2" style="color: var(--accent-active);"></i>
                                        1. Цель и стиль изображения
                                    </h3>
                                    <!-- <i class="fas fa-chevron-down transition-transform"></i> -->
                                </div>
                            </div>
                            <div class="accordion-content">
                                <p class="mb-3">Определяет общее назначение и художественное направление изображения.</p>
                                <div class="code-block">
                                    <h4>Пример:</h4>
                                    <pre>{
  "image_purpose": "product_showcase",
  "style": "photorealistic, minimalist"
}</pre>
                                </div>
                                <ul class="mt-3 space-y-1 text-sm">
                                    <li><strong>image_purpose:</strong> "portrait", "still_life", "cinematic_storytelling", "concept_art"</li>
                                    <li><strong>style:</strong> "realistic photography", "watercolor", "cyberpunk", "studio Ghibli"</li>
                                </ul>
                            </div>
                        </div>

                        <!-- Элемент 2: Субъект -->
                        <div class="accordion">
                            <div class="accordion-header" onclick="toggleAccordion(this)">
                                <div class="flex justify-between items-center">
                                    <h3 class="font-semibold">
                                        <i class="fas fa-user mr-2" style="color: var(--accent-active);"></i>
                                        2. Субъект и действие
                                    </h3>
                                    <!-- <i class="fas fa-chevron-down transition-transform"></i> -->
                                </div>
                            </div>
                            <div class="accordion-content">
                                <p class="mb-3">Детальное описание главного объекта, персонажа или сцены.</p>
                                <div class="code-block">
                                    <h4>Пример:</h4>
                                    <pre>{
  "subject": "Dark-haired detective wearing futuristic coat, 
             standing on rooftop, looking over neon-lit city"
}</pre>
                                </div>
                                <p class="mt-3 text-sm"><strong>Совет:</strong> Будьте конкретны  - указывайте детали внешности, позу, действия, реквизит.</p>
                            </div>
                        </div>

                        <!-- Элемент 3: Сцена -->
                        <div class="accordion">
                            <div class="accordion-header" onclick="toggleAccordion(this)">
                                <div class="flex justify-between items-center">
                                    <h3 class="font-semibold">
                                        <i class="fas fa-map-marked-alt mr-2" style="color: var(--accent-active);"></i>
                                        3. Окружение и сцена
                                    </h3>
                                    <!-- <i class="fas fa-chevron-down transition-transform"></i> -->
                                </div>
                            </div>
                            <div class="accordion-content">
                                <p class="mb-3">Описывает место действия, фон и поверхности.</p>
                                <div class="code-block">
                                    <h4>Пример:</h4>
                                    <pre>{
  "scene": {
    "environment": "studio",
    "background": {
      "material": "seamless paper",
      "color_tone": "neutral-cool",
      "cleanliness": "clean"
    },
    "surface": {
      "material": "glass"
    }
  }
}</pre>
                                </div>
                                <ul class="mt-3 space-y-1 text-sm">
                                    <li><strong>environment:</strong> "studio", "interior", "exterior", "urban"</li>
                                    <li><strong>background:</strong> материал, цветовой тон, чистота/текстура</li>
                                    <li><strong>surface:</strong> поверхность для натюрмортов (дерево, камень, металл)</li>
                                </ul>
                            </div>
                        </div>

                        <!-- Элемент 4: Освещение -->
                        <div class="accordion">
                            <div class="accordion-header" onclick="toggleAccordion(this)">
                                <div class="flex justify-between items-center">
                                    <h3 class="font-semibold">
                                        <i class="fas fa-lightbulb mr-2" style="color: var(--accent-active);"></i>
                                        4. Освещение
                                    </h3>
                                    <!-- <i class="fas fa-chevron-down transition-transform"></i> -->
                                </div>
                            </div>
                            <div class="accordion-content">
                                <p class="mb-3">Контролирует тип, направление и качество света.</p>
                                <div class="code-block">
                                    <h4>Пример:</h4>
                                    <pre>{
  "lighting": {
    "type": "natural",
    "direction": "left, 45 degrees",
    "quality": "soft, diffused"
  }
}</pre>
                                </div>
                                <ul class="mt-3 space-y-1 text-sm">
                                    <li><strong>type:</strong> "natural", "strobe", "continuous", "neon", "candlelight"</li>
                                    <li><strong>direction:</strong> "top", "left", "right", "back (rim lighting)", "front"</li>
                                    <li><strong>quality:</strong> "soft", "hard", "diffused", "dramatic"</li>
                                </ul>
                            </div>
                        </div>

                        <!-- Элемент 5: Камера -->
                        <div class="accordion">
                            <div class="accordion-header" onclick="toggleAccordion(this)">
                                <div class="flex justify-between items-center">
                                    <h3 class="font-semibold">
                                        <i class="fas fa-camera mr-2" style="color: var(--accent-active);"></i>
                                        5. Настройки камеры
                                    </h3>
                                    <!-- <i class="fas fa-chevron-down transition-transform"></i> -->
                                </div>
                            </div>
                            <div class="accordion-content">
                                <p class="mb-3">Определяет технические параметры съёмки и ракурс.</p>
                                <div class="code-block">
                                    <h4>Пример:</h4>
                                    <pre>{
  "camera": {
    "lens": "50mm",
    "aperture": "f/1.8",
    "angle": "low-angle shot, wide",
    "movement": "slow zoom-in"
  }
}</pre>
                                </div>
                                <ul class="mt-3 space-y-1 text-sm">
                                    <li><strong>lens:</strong> "24mm" (широкоугольный), "50mm" (стандарт), "100mm" (макро)</li>
                                    <li><strong>aperture:</strong> "f/1.8" (малая глубина резкости), "f/8" (всё в фокусе)</li>
                                    <li><strong>angle:</strong> "close-up", "wide shot", "bird's eye view", "low-angle"</li>
                                    <li><strong>movement:</strong> (для видео) "dolly zoom", "pan", "tilt"</li>
                                </ul>
                            </div>
                        </div>

                        <!-- Элемент 6: Настроение -->
                        <div class="accordion">
                            <div class="accordion-header" onclick="toggleAccordion(this)">
                                <div class="flex justify-between items-center">
                                    <h3 class="font-semibold">
                                        <i class="fas fa-palette mr-2" style="color: var(--accent-active);"></i>
                                        6. Настроение и эмоции
                                    </h3>
                                    <!-- <i class="fas fa-chevron-down transition-transform"></i> -->
                                </div>
                            </div>
                            <div class="accordion-content">
                                <p class="mb-3">Добавляет эмоциональный контекст и общую атмосферу.</p>
                                <div class="code-block">
                                    <h4>Пример:</h4>
                                    <pre>{
  "mood_emotion": "dark, melancholic, suspenseful"
}</pre>
                                </div>
                                <p class="mt-3 text-sm"><strong>Варианты:</strong> "dramatic", "joyful", "mysterious", "peaceful", "epic", "sophisticated"</p>
                            </div>
                        </div>
                    </div>
                </section>

                <!-- Практические примеры -->
                <section class="content-section">
                    <h2 class="text-3xl font-bold mb-6">
                        <i class="fas fa-flask mr-3" style="color: var(--accent-active);"></i>
                        Практические примеры JSON - промптов
                    </h2>

                    <div class="space-y-6">
                        <!-- Пример 1: Продуктовая фотография -->
                        <div class="example-card">
                            <div class="flex items-start mb-4">
                                <div class="bg-blue-100 p-3 rounded-full mr-4">
                                    <i class="fas fa-shopping-bag text-2xl text-blue-600"></i>
                                </div>
                                <div>
                                    <h3 class="text-xl font-bold mb-2">Пример 1: Продуктовая фотография (E - commerce)</h3>
