        .timeline {
            position: relative;
            padding-left: 2rem;
        }

        .timeline-item {
            position: relative;
            margin: 2rem 0;
            padding: 1.5rem;
            background: var(--block-bg);
            border-radius: 8px;
        }

        .timeline-item::before {
            content: '';
            position: absolute;
            left: -2.5rem;
            top: 1rem;
            width: 12px;
            height: 12px;
            background: var(--accent-active);
            border-radius: 50%;
        }

        .timeline-item::after {
            content: '';
            position: absolute;
            left: -2rem;
            top: 1.75rem;
            width: 2px;
            height: calc(100% + 2rem);
            background: var(--accent-inactive);
        }

        .timeline-item:last-child::after {
            display: none;
        }




.flip-card {
    background-color: transparent;
    width: 100%;
    height: 150px;
    perspective: 1000px;
    margin: 0.75rem 0;
}

.flip-card-inner {
    position: relative;
    width: 100%;
    height: 100%;
    text-align: center;
    transition: transform 0.6s;
    transform-style: preserve-3d;
    cursor: pointer;
}

.flip-card.flipped .flip-card-inner { transform: rotateY(180deg); }

.flip-card-front, .flip-card-back {
    position: absolute;
    width: 100%;
    height: 100%;
    backface-visibility: hidden;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.1);
    flex-direction: column;
    text-align: center;
    overflow: hidden;
    box-sizing: border-box;
}

.flip-card-front { background-color: var(--block-bg); }
.flip-card-back { background-color: var(--accent-active); color: white; transform: rotateY(180deg); }










        .checklist-item {
            background: white;
            border-radius: 8px;
            padding: 1rem;
            margin: 0.5rem 0;
            border: 1px solid #e5e5e5;
            transition: all 0.3s ease;
        }

        .checklist-item.completed {
            background: #f0f9ff;
            border-color: #3b82f6;
        }

        .risk-meter {
            height: 20px;
            background: #e5e5e5;
            border-radius: 10px;
            overflow: hidden;
            margin: 0.5rem 0;
        }

        .risk-meter-fill {
            height: 100%;
            transition: width 0.5s ease;
            border-radius: 10px;
        }

        .risk-low { background: #10b981; }
        .risk-medium { background: #f59e0b; }
        .risk-high { background: var(--accent-active); }

        .classic-link {
            color: var(--accent-active);
            text-decoration: none;
        }

        .classic-link:hover {
            text-decoration: underline;
            color: #c4050f;
        }

        .security-demo {
            background: #1f2937;
            color: #f9fafb;
            border-radius: 8px;
            padding: 1rem;
