   <script>
    // Основная система управления табами
    document.addEventListener('DOMContentLoaded', function() {
        console.log('🚀 Инициализация системы табов');

        // Переменные для отслеживания прогресса (если нужно)
        let completedSteps = 0;
        let scrollProgress = false;

        // Функция для переключения табов
        function switchTab(targetTab) {
            console.log(`🔄 Переключение на таб: ${targetTab}`);

            // Удаляем активный класс со всех кнопок табов
            const allTabButtons = document.querySelectorAll('.tab-button');
            allTabButtons.forEach(button => {
                button.classList.remove('active');
            });

            // Скрываем все контентные блоки табов
            const allTabContent = document.querySelectorAll('.tab-content');
            allTabContent.forEach(content => {
                content.style.display = 'none';
                content.classList.remove('active');
            });

            // Активируем все кнопки табов с соответствующим data-tab
            const targetButtons = document.querySelectorAll(`[data-tab="${targetTab}"]`);
            targetButtons.forEach(button => {
                button.classList.add('active');
                console.log(`✅ Кнопка таба "${targetTab}" активирована`);
            });

            // Показываем целевой контент
            const targetContent = document.getElementById(targetTab);
            if (targetContent) {
                targetContent.style.display = 'block';
                targetContent.classList.add('active');
                console.log(`✅ Контент таба "${targetTab}" показан`);

                // Прокрутка до самого верха страницы
                window.scrollTo({
                    top: 0,
                    behavior: 'smooth'
                });
            } else {
                console.error(`❌ Контент для таба "${targetTab}" не найден`);
            }
        }

        // Находим все кнопки табов
        const tabButtons = document.querySelectorAll('.tab-button');
        console.log(`📋 Найдено ${tabButtons.length} кнопок табов`);

        // Добавляем обработчики клика для всех кнопок табов
        tabButtons.forEach(button => {
            const tabId = button.getAttribute('data-tab');
            console.log(`🔗 Настройка обработчика для таба: ${tabId}`);

            button.addEventListener('click', function(e) {
                e.preventDefault();
                switchTab(tabId);

                // Обновляем URL
                history.pushState(null, null, `#${tabId}`);
            });
        });

        // Определяем начальный активный таб
        let activeTab = null;

        // Проверяем, есть ли уже активный таб в URL
        const hash = window.location.hash.substring(1);
        if (hash && document.getElementById(hash)) {
            activeTab = hash;
            console.log(`🎯 Активный таб из URL: ${activeTab}`);
        } else {
            // Ищем активную кнопку в HTML
            const activeButton = document.querySelector('.tab-button.active');
            if (activeButton) {
                activeTab = activeButton.getAttribute('data-tab');
                console.log(`🎯 Найден активный таб в HTML: ${activeTab}`);
            }
        }

        // Если активный таб не найден, используем первый доступный
        if (!activeTab && tabButtons.length > 0) {
            activeTab = tabButtons[0].getAttribute('data-tab');
            console.log(`🎯 Установлен первый таб по умолчанию: ${activeTab}`);
        }

        // Применяем начальное состояние
        if (activeTab) {
            switchTab(activeTab);
        }



















        // Обрабатываем изменение хэша в URL
        window.addEventListener('hashchange', function() {
            const hash = window.location.hash.substring(1);
            if (hash && document.getElementById(hash)) {
                switchTab(hash);
            }
        });

        // Инициализация системы шеринга
        setupShareTools();

        console.log('✨ Система табов успешно инициализирована');
    });

    // Система шеринга
    function setupShareTools() {
        const pageUrl = window.location.href;
        const encodedPageUrl = encodeURIComponent(pageUrl);
        const pageTitle = encodeURIComponent(document.title);
        const pageTitleText = document.title; 

        const shareLinks = {
            vk: `https://vk.com/share.php?url=${encodedPageUrl}&title=${pageTitle}`,
            telegram: `https://t.me/share/url?url=${encodedPageUrl}&text=${pageTitle}`,
            whatsapp: `https://wa.me/?text=${pageTitle}%20${encodedPageUrl}`,
            facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodedPageUrl}`,
            email: `mailto:?subject=${pageTitleText}&body=Рекомендую ознакомиться с материалом: ${pageUrl}`
        };

        // Устанавливаем ссылки для кнопок шеринга
        for (const [id, url] of Object.entries(shareLinks)) {
            const element = document.getElementById(`share-${id}`);
            if (element) {
                element.href = url;
                if (id !== 'email') {
                    element.target = '_blank';
                    element.rel = 'noopener noreferrer';
                }
            }
        }

        // Логика для кнопки "Копировать ссылку"
        const copyButton = document.getElementById('copy-link-button');
        const copyFeedback = document.getElementById('copy-feedback');
        const copyIcon = document.getElementById('copy-link-icon');

        if (copyButton) {
            copyButton.addEventListener('click', function() {
                navigator.clipboard.writeText(pageUrl).then(function() {
                    copyFeedback.textContent = 'Ссылка скопирована!';
                    copyIcon.className = 'fas fa-check';

                    setTimeout(() => { 
                        copyFeedback.textContent = '';
                        copyIcon.className = 'fas fa-link';
                    }, 2500);
                }).catch(function(err) {
                    copyFeedback.textContent = 'Ошибка при копировании';
                    console.error('Не удалось скопировать ссылку: ', err);
                    setTimeout(() => { copyFeedback.textContent = ''; }, 2500);
                });
            });
        }

        // Генерация QR-кода
        const qrCodeContainer = document.getElementById('qrcode');
        if(qrCodeContainer && typeof QRCode !== 'undefined') {
            // Очищаем контейнер перед созданием нового QR-кода
            qrCodeContainer.innerHTML = '';
            new QRCode(qrCodeContainer, {
                text: pageUrl,
                width: 128,
                height: 128,
                colorDark : "#000000",
                colorLight : "#ffffff",
                correctLevel : QRCode.CorrectLevel.H
            });
        }
    }

    // Дополнительные функции (если нужны)
    function flipCard(card) {
        card.classList.toggle('flipped');
    }

    function toggleChecklistItem(item) {
        const checkbox = item.querySelector('input[type="checkbox"]');
        if (checkbox) {
            checkbox.checked = !checkbox.checked;

            if (checkbox.checked) {
                item.classList.add('completed');
            } else {
                item.classList.remove('completed');
            }
        }
    }


// Система шеринга
function setupShareTools() {
