                'plan': 'На основе анализа агент создает детальный план действий, определяет последовательность шагов и выбирает необходимые инструменты для выполнения задачи.',
                'act': 'Агент приступает к выполнению плана, используя доступные инструменты и ресурсы. Может взаимодействовать с внешними системами и API.',
                'reflect': 'После выполнения агент анализирует результаты, определяет успешность действий и сохраняет полученный опыт для улучшения будущих решений.'
            };

            // Сброс активных состояний
            document.querySelectorAll('.flow-step').forEach(s => s.classList.remove('active'));

            // Активация выбранного шага
            document.querySelector(`[data-step="${step}"]`).classList.add('active');

            // Показ деталей
            const detailsDiv = document.getElementById('step-details');
            const descriptionP = document.getElementById('step-description');

            descriptionP.innerHTML = details[step];
            detailsDiv.classList.remove('hidden');

            completedSteps++;
            updateProgress();
        }

        // Выбор фреймворка
        function selectFramework(card, type) {
            document.querySelectorAll('.framework-card').forEach(c => c.classList.remove('selected'));
            card.classList.add('selected');

            completedSteps++;
            updateProgress();
        }



// Квизы
        document.querySelectorAll('.quiz-option').forEach(option => {
            option.addEventListener('click', function() {
                const question = this.closest('.quiz-question');
                const options = question.querySelectorAll('.quiz-option');
                const feedback = question.querySelector('.quiz-feedback');
                const isCorrect = this.getAttribute('data-correct') === 'true';

                // Отключение кликов
                options.forEach(opt => {
                    opt.style.pointerEvents = 'none';
                    if (opt.getAttribute('data-correct') === 'true') {
                        opt.classList.add('correct');
                    } else if (opt === this && !isCorrect) {
                        opt.classList.add('incorrect');
                    }
                });

                // Показ обратной связи
                feedback.classList.remove('hidden');
                if (isCorrect) {
                    feedback.innerHTML = '<p class="text-green-600">✓ Правильно!</p>';
                } else {
                    feedback.innerHTML = '<p class="text-red-600">✗ Неправильно. Правильный ответ выделен зеленым.</p>';
                }
            });
        });







        // Флип-карточки
        document.querySelectorAll('.flip-card').forEach(card => {
            card.addEventListener('click', function() {
                this.classList.toggle('flipped');
            });
        });

        // Обработка скролла для прогресса
        let scrollProgress = false;
        window.addEventListener('scroll', function() {
            if (!scrollProgress && window.scrollY > 500) {
                scrollProgress = true;
                completedSteps++;
                updateProgress();
            }
        });















    </script>
</body>
</html>
